INSERT INTO grammar.content_catalog_topics(version,slug,catalog_hash,payload) VALUES('core-2026-09-v3','conditionals','e49c6c64b6333354230b05b223ded19e0e7519c1828bf3f36aee778f9f3f39c4','{"slug":"conditionals","title":"Zero, first and second conditionals","level":"B1","order":42,"summary":"Express regular consequences, realistic future possibilities and imagined alternatives.","guidance":"Read the form and meaning together. Study the contrasts, then explain a worked example in your own words before starting a fresh practice session.","learningGoals":["General conditions","A realistic future possibility","An imagined present or future","Clause order and unless"],"rules":[{"title":"General conditions","explanation":"A common **zero conditional** uses present simple in both clauses for a regular consequence or general relationship. If can sometimes be replaced by when when the event is expected or repeated. It is the general meaning, not only the verb forms, that matters.","pattern":"If water freezes, it **expands**.","commonMistakes":["A conditional can also contain an instruction: If you need help, ask. Not every if sentence belongs to one numbered formula."],"examples":["State a regular procedure in the zero conditional: “Whenever an order arrives, she **prepares** the visitor guide.”","State a regular procedure in the zero conditional: “Whenever an order arrives, she **restores** the old portrait.”"],"skill":"form"},{"title":"A realistic future possibility","explanation":"The usual **first conditional** has if + present simple, followed by will + base verb. It treats the condition as a realistic possibility. The result can also use can, may or an imperative when that meaning is appropriate.","pattern":"If she **calls**, I **will answer**.","commonMistakes":["In an ordinary future condition, do not put will in the if clause. Will can occur there with other meanings, such as willingness."],"examples":["Use the standard first conditional: “If she **prepares** the visitor guide tomorrow, we will be ready.”","Use the standard first conditional: “If she **restores** the old portrait tomorrow, we will be ready.”"],"skill":"meaning"},{"title":"An imagined present or future","explanation":"A common **second conditional** uses if + past simple with would + base verb. The past form marks distance from reality rather than necessarily past time. Were is common for all subjects in formal hypothetical be clauses, especially If I were you.","pattern":"If I **had** time, I **would visit**.","commonMistakes":["The form does not mean the imagined event happened in the past; it often concerns now or the future."],"examples":["Use the second conditional for an imagined situation now: “If she **prepared** the visitor guide, we would have less work.”","Use the second conditional for an imagined situation now: “If she **restored** the old portrait, we would have less work.”"],"skill":"contrast"},{"title":"Clause order and unless","explanation":"The clauses can swap order without changing the basic relationship. A leading if clause is normally followed by a comma. Unless often means if not, but replacing every negative condition mechanically can change meaning.","pattern":"If it rains, we’ll stay. / We’ll stay if it rains.","commonMistakes":["Do not add a second negative merely because unless already has an if-not meaning."],"examples":["Complete the second-conditional result: “If I had more time now, I **would prepare** the visitor guide.”","Complete the second-conditional result: “If I had more time now, I **would restore** the old portrait.”"],"skill":"application"}],"tips":[],"source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-conditionals"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"quizItems":[{"id":"1194163c-0479-54ec-ac4a-d3b4379dc842","topicSlug":"conditionals","level":"B1","prompt":"State a regular procedure in the zero conditional: “Whenever an order arrives, she ____ the visitor guide.”","choices":[{"id":"A","text":"prepare"},{"id":"B","text":"will to prepare"},{"id":"C","text":"preparing"},{"id":"D","text":"prepares"}],"answerId":"D","hint":"A **regular procedure** uses present simple in both clauses; then check subject–verb agreement.","explanation":"This describes a repeated procedure, so the zero-conditional result uses present simple **prepares**, agreeing with she.","keywords":["zero-result"],"skill":"zero-result","contextKey":"conditionals-1","fingerprint":"944a05af28c3d38d1cb87e0900e15132607c9a35d40d4702b6e4af811616b117","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-conditionals"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["A **regular procedure** uses present simple in both clauses; then check subject–verb agreement.","This describes a repeated procedure, so the zero-conditional result uses present simple **prepares**, agreeing with she.","Choose **prepares**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"The present-simple verb needs third-person -s with she.","B":"Will cannot be followed by to; the task also asks for a regular present procedure.","C":"An -ing form alone is not a finite verb for this result.","D":"This describes a repeated procedure, so the zero-conditional result uses present simple **prepares**, agreeing with she."}}},{"id":"66ea4f52-c4c4-55d6-ab0a-b3ce5c3711c3","topicSlug":"conditionals","level":"B1","prompt":"Use the standard first conditional: “If she ____ the visitor guide tomorrow, we will be ready.”","choices":[{"id":"A","text":"prepares"},{"id":"B","text":"will prepare"},{"id":"C","text":"would prepare"},{"id":"D","text":"preparing"}],"answerId":"A","hint":"This is a **real future possibility**; use present simple after if.","explanation":"The ordinary future if-clause uses present simple: **she prepares**.","keywords":["first-if-clause"],"skill":"first-if-clause","contextKey":"conditionals-1","fingerprint":"6346bd2b790e09514922514ce794636178107127a87ff73e8905067c2ee65ff1","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-conditionals"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["This is a **real future possibility**; use present simple after if.","The ordinary future if-clause uses present simple: **she prepares**.","Choose **prepares**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"The ordinary future if-clause uses present simple: **she prepares**.","B":"Will normally belongs in the result clause for this ordinary future condition.","C":"Would would create the wrong form for the requested if-clause.","D":"The -ing form alone is not a finite predicate."}}},{"id":"709f2f32-55bb-5efc-a1b8-33869d7f3553","topicSlug":"conditionals","level":"B1","prompt":"Use the second conditional for an imagined situation now: “If she ____ the visitor guide, we would have less work.”","choices":[{"id":"A","text":"prepared"},{"id":"B","text":"prepares"},{"id":"C","text":"would prepare"},{"id":"D","text":"preparing"}],"answerId":"A","hint":"The past form here expresses an **imagined alternative**, not a completed past event.","explanation":"The hypothetical if-clause uses past-form **prepared** to mark distance from reality.","keywords":["second-if-clause"],"skill":"second-if-clause","contextKey":"conditionals-1","fingerprint":"d913c1860b10f236d383aca46255e7b7ff2a0a0a0b0c3ffc439a930bc29411d3","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-conditionals"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["The past form here expresses an **imagined alternative**, not a completed past event.","The hypothetical if-clause uses past-form **prepared** to mark distance from reality.","Choose **prepared**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"The hypothetical if-clause uses past-form **prepared** to mark distance from reality.","B":"The requested second-conditional if-clause uses a past form, not present -s.","C":"Would belongs in the result clause in this standard pattern.","D":"An -ing form alone is not a finite clause verb."}}},{"id":"dc276870-0095-55c8-ac19-a0f3deb0afa2","topicSlug":"conditionals","level":"B1","prompt":"Complete the second-conditional result: “If I had more time now, I ____ the visitor guide.”","choices":[{"id":"A","text":"would to prepare"},{"id":"B","text":"would prepared"},{"id":"C","text":"would preparing"},{"id":"D","text":"would prepare"}],"answerId":"D","hint":"Match **if + past** with **would + base verb** in this standard hypothetical pattern.","explanation":"An imagined present result takes **would + prepare**.","keywords":["second-result"],"skill":"second-result","contextKey":"conditionals-1","fingerprint":"a9144410a86542a31eeaeaaa5d9c8a6ac082f992234db68aa85553831ec7e749","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-conditionals"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["Match **if + past** with **would + base verb** in this standard hypothetical pattern.","An imagined present result takes **would + prepare**.","Choose **would prepare**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"Would takes a bare infinitive without to.","B":"A past form cannot directly follow would.","C":"Would needs be before -ing; this task asks for the simple result pattern.","D":"An imagined present result takes **would + prepare**."}}},{"id":"808031c0-f53d-5f07-a50b-a512863b3f91","topicSlug":"conditionals","level":"B1","prompt":"State a regular procedure in the zero conditional: “Whenever an order arrives, she ____ the old portrait.”","choices":[{"id":"A","text":"restoring"},{"id":"B","text":"restores"},{"id":"C","text":"restore"},{"id":"D","text":"will to restore"}],"answerId":"B","hint":"A **regular procedure** uses present simple in both clauses; then check subject–verb agreement.","explanation":"This describes a repeated procedure, so the zero-conditional result uses present simple **restores**, agreeing with she.","keywords":["zero-result"],"skill":"zero-result","contextKey":"conditionals-2","fingerprint":"8366c03e938485dd714d8114d6487728cfb663a79b5397c5edda642e0bf214c2","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-conditionals"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["A **regular procedure** uses present simple in both clauses; then check subject–verb agreement.","This describes a repeated procedure, so the zero-conditional result uses present simple **restores**, agreeing with she.","Choose **restores**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"An -ing form alone is not a finite verb for this result.","B":"This describes a repeated procedure, so the zero-conditional result uses present simple **restores**, agreeing with she.","C":"The present-simple verb needs third-person -s with she.","D":"Will cannot be followed by to; the task also asks for a regular present procedure."}}},{"id":"212fa49d-17f4-5577-a3c4-bd4e7e9434f8","topicSlug":"conditionals","level":"B1","prompt":"Use the standard first conditional: “If she ____ the old portrait tomorrow, we will be ready.”","choices":[{"id":"A","text":"would restore"},{"id":"B","text":"restoring"},{"id":"C","text":"restores"},{"id":"D","text":"will restore"}],"answerId":"C","hint":"This is a **real future possibility**; use present simple after if.","explanation":"The ordinary future if-clause uses present simple: **she restores**.","keywords":["first-if-clause"],"skill":"first-if-clause","contextKey":"conditionals-2","fingerprint":"6dfa17ef2424fbabc5287d07ad36717e1dc3eea67c03ac2e784697ad12452f6d","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-conditionals"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["This is a **real future possibility**; use present simple after if.","The ordinary future if-clause uses present simple: **she restores**.","Choose **restores**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"Would would create the wrong form for the requested if-clause.","B":"The -ing form alone is not a finite predicate.","C":"The ordinary future if-clause uses present simple: **she restores**.","D":"Will normally belongs in the result clause for this ordinary future condition."}}},{"id":"652ef459-461e-5d86-af09-308dd72b6efb","topicSlug":"conditionals","level":"B1","prompt":"Use the second conditional for an imagined situation now: “If she ____ the old portrait, we would have less work.”","choices":[{"id":"A","text":"restoring"},{"id":"B","text":"restored"},{"id":"C","text":"restores"},{"id":"D","text":"would restore"}],"answerId":"B","hint":"The past form here expresses an **imagined alternative**, not a completed past event.","explanation":"The hypothetical if-clause uses past-form **restored** to mark distance from reality.","keywords":["second-if-clause"],"skill":"second-if-clause","contextKey":"conditionals-2","fingerprint":"30f835752ac5f953a2a4e12c125080390444a7638f4d080ecbd0deab345d8aa2","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-conditionals"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["The past form here expresses an **imagined alternative**, not a completed past event.","The hypothetical if-clause uses past-form **restored** to mark distance from reality.","Choose **restored**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"An -ing form alone is not a finite clause verb.","B":"The hypothetical if-clause uses past-form **restored** to mark distance from reality.","C":"The requested second-conditional if-clause uses a past form, not present -s.","D":"Would belongs in the result clause in this standard pattern."}}},{"id":"017417a5-7fb7-5438-afd3-399338f8e038","topicSlug":"conditionals","level":"B1","prompt":"Complete the second-conditional result: “If I had more time now, I ____ the old portrait.”","choices":[{"id":"A","text":"would restore"},{"id":"B","text":"would to restore"},{"id":"C","text":"would restored"},{"id":"D","text":"would restoring"}],"answerId":"A","hint":"Match **if + past** with **would + base verb** in this standard hypothetical pattern.","explanation":"An imagined present result takes **would + restore**.","keywords":["second-result"],"skill":"second-result","contextKey":"conditionals-2","fingerprint":"5a76a815a9392ee7a0314eee9e18f6646dbac30710786817620a5d1b09277b56","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-conditionals"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["Match **if + past** with **would + base verb** in this standard hypothetical pattern.","An imagined present result takes **would + restore**.","Choose **would restore**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"An imagined present result takes **would + restore**.","B":"Would takes a bare infinitive without to.","C":"A past form cannot directly follow would.","D":"Would needs be before -ing; this task asks for the simple result pattern."}}},{"id":"152c260f-5916-562c-ac27-0480742d6ada","topicSlug":"conditionals","level":"B1","prompt":"State a regular